CREATE TABLE sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(40) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,display_name VARCHAR(40) NOT NULL,role VARCHAR(20) NOT NULL,enabled BOOLEAN NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE plm_product (id BIGINT PRIMARY KEY AUTO_INCREMENT,product_code VARCHAR(32) NOT NULL UNIQUE,product_name VARCHAR(100) NOT NULL,model VARCHAR(60) NOT NULL,version VARCHAR(20) NOT NULL,lifecycle_stage VARCHAR(24) NOT NULL,owner VARCHAR(40) NOT NULL,status VARCHAR(24) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE plm_part (id BIGINT PRIMARY KEY AUTO_INCREMENT,part_no VARCHAR(32) NOT NULL UNIQUE,part_name VARCHAR(100) NOT NULL,category VARCHAR(32) NOT NULL,version VARCHAR(20) NOT NULL,specification VARCHAR(120) NOT NULL,unit VARCHAR(20) NOT NULL,status VARCHAR(24) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE plm_bom_item (id BIGINT PRIMARY KEY AUTO_INCREMENT,product_code VARCHAR(32) NOT NULL,parent_part_no VARCHAR(32),child_part_no VARCHAR(32) NOT NULL,level_no INT NOT NULL,quantity DOUBLE NOT NULL,unit VARCHAR(12) NOT NULL,effectivity VARCHAR(20) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE plm_change_request (id BIGINT PRIMARY KEY AUTO_INCREMENT,change_no VARCHAR(32) NOT NULL UNIQUE,title VARCHAR(140) NOT NULL,product_code VARCHAR(32) NOT NULL,change_type VARCHAR(20) NOT NULL,reason VARCHAR(300) NOT NULL,owner VARCHAR(40) NOT NULL,due_date DATE NOT NULL,risk_level VARCHAR(16) NOT NULL,status VARCHAR(24) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE plm_technical_document (id BIGINT PRIMARY KEY AUTO_INCREMENT,document_no VARCHAR(32) NOT NULL UNIQUE,title VARCHAR(140) NOT NULL,category VARCHAR(32) NOT NULL,version VARCHAR(20) NOT NULL,product_code VARCHAR(32) NOT NULL,owner VARCHAR(40) NOT NULL,status VARCHAR(24) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE INDEX idx_plm_product_stage ON plm_product(lifecycle_stage); CREATE INDEX idx_plm_bom_product ON plm_bom_item(product_code); CREATE INDEX idx_plm_change_status ON plm_change_request(status); CREATE INDEX idx_plm_document_product ON plm_technical_document(product_code);
